
CREATE TABLE IF NOT EXISTS villages_census_raw (
  id SERIAL PRIMARY KEY,
  village_code_2011 TEXT NOT NULL UNIQUE,
  village_name TEXT NOT NULL,
  tehsil_code TEXT NOT NULL,
  tehsil_name TEXT NOT NULL,
  total_population INT,
  total_households INT,
  sc_population INT,
  st_population INT,
  literacy_rate NUMERIC,
  has_name_duplicate_in_tehsil BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX IF NOT EXISTS idx_villages_census_raw_tehsil ON villages_census_raw(tehsil_name);
CREATE INDEX IF NOT EXISTS idx_villages_census_raw_name ON villages_census_raw(village_name);


